    public function sync(): void
    {
        if(!Schema::hasTable('store_items')) return;
        foreach(array_merge($this->pashaItems(), $this->tableSkins(), $this->cardBacks(), $this->v021TableCardBacks(), $this->nameFrames(), $this->v173NonTableItems(), $this->v183Items()) as $item) $this->upsert($item);
        // v131: remove duplicates and keep one clean Pasha plan per duration.
        $keep=array_column($this->pashaItems(),'key');
        DB::table('store_items')->where('category','pasha')->whereNotIn('key',$keep)->update(['active'=>false,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->whereIn('duration_days',[1,3,7,30,90,365])->whereNotIn('key',$keep)->update(['active'=>false,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('duration_days',7)->where('key','!=','pasha_7_days_v128')->update(['active'=>false,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('duration_days',30)->where('key','!=','pasha_30_days_v128')->update(['active'=>false,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('duration_days',365)->where('key','!=','pasha_365_days_v128')->update(['active'=>false,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('key','pasha_7_days_v128')->update(['price'=>10000,'duration_days'=>7,'active'=>true,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('key','pasha_30_days_v128')->update(['price'=>38000,'duration_days'=>30,'active'=>true,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('key','pasha_365_days_v128')->update(['price'=>300000,'duration_days'=>365,'active'=>true,'updated_at'=>now()]);
        // v172: keep the curated legacy 50 plus the additive 40-table HD reference collection; hide only obsolete rows.
        $tableKeep=array_column($this->tableSkins(),'key');
        DB::table('store_items')->where('category','table')->whereNotIn('key',$tableKeep)->update(['active'=>false,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('key','pasha_1_day_v132')->update(['price'=>1700,'duration_days'=>1,'active'=>true,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('key','pasha_3_days_v132')->update(['price'=>5000,'duration_days'=>3,'active'=>true,'updated_at'=>now()]);
        DB::table('store_items')->where('category','pasha')->where('key','pasha_90_days_v132')->update(['price'=>105000,'duration_days'=>90,'active'=>true,'updated_at'=>now()]);
        DB::table('store_items')->where('key','pasha_style_black_v173')->update(['active'=>false,'updated_at'=>now()]);
        // V183: remove the four temporary reference-table batches from all storefronts.
        DB::table('store_items')->where('category','table')->where('key','like','table_reference_%')->update(['active'=>false,'updated_at'=>now()]);
        // Keep exactly the seven color boosters active. Legacy booster rows remain for historical inventory only.
        $boostKeep=array_column(array_filter($this->v183Items(),fn(array $i)=>($i['category'] ?? '')==='xp_booster'),'key');
        DB::table('store_items')->where('category','xp_booster')->whereNotIn('key',$boostKeep)->update(['active'=>false,'updated_at'=>now()]);
        foreach($this->v201Items() as $item) $this->upsert($item);
        foreach($this->v201R4Items() as $item) $this->upsert($item);
        foreach($this->v202Items() as $item) $this->upsert($item);
        foreach($this->v300WorldItems() as $item) $this->upsert($item);
        $this->normalizeAllActivePricesR91();
        $this->normalizeBilingualNames();
        $this->deactivateExactDuplicates();
        $this->syncB304VerticalLegend();
        $this->grantPrimaryAdminAllCollectibles();

    }


    /** R9.1: the primary admin is treated as having purchased every current collectible. */
    public function grantPrimaryAdminAllCollectibles(): void
    {
        if(!Schema::hasTable('users') || !Schema::hasTable('store_items') || !Schema::hasTable('inventory_items')) return;
        $admin=\App\Models\User::where('is_admin',true)->where('admin_role','primary_admin')->first() ?: \App\Models\User::whereRaw('LOWER(username) = ?', ['adnan'])->where('is_admin',true)->first();
        if(!$admin) return;
        $items=\App\Models\StoreItem::where('active',true)->whereNotIn('category',['pasha','competition_ticket'])->get();
        foreach($items as $item) $this->grantPrimaryAdminItem((int)$item->id, $admin);
    }

    public function grantPrimaryAdminItem(int $storeItemId, ?\App\Models\User $admin=null): void
    {
        if(!Schema::hasTable('inventory_items')) return;
        $admin ??= \App\Models\User::where('is_admin',true)->where('admin_role','primary_admin')->first() ?: \App\Models\User::whereRaw('LOWER(username) = ?', ['adnan'])->where('is_admin',true)->first();
        $item=\App\Models\StoreItem::find($storeItemId);
        if(!$admin || !$item || !$item->active || in_array($item->category,['pasha','competition_ticket'],true)) return;
        \App\Models\InventoryItem::updateOrCreate(
            ['user_id'=>$admin->id,'store_item_id'=>$item->id],
            ['active'=>false,'activated_at'=>null,'expires_at'=>null]
        );
    }

    private function upsert(array $item): void
    {
        $names=[];
        foreach(['ar','en'] as $locale) {
            $names[$locale]=(string)($item[$locale] ?? $item['en'] ?? $item['ar'] ?? $item['key']);
        }
        $payload=(array)($item['payload'] ?? []);
        if(($item['category'] ?? '')!=='pasha'){
            $payload['r91_price_normalized']=true;
            $payload['r91_base_price']=(int)($item['price'] ?? 0);
        }
        DB::table('store_items')->updateOrInsert(['key'=>$item['key']],[
            'name'=>json_encode($names,JSON_UNESCAPED_UNICODE),
            'category'=>$item['category'],
            'price'=>$this->v183Price($item),
            'duration_days'=>$item['duration_days'] ?? null,
            'payload'=>json_encode($payload,JSON_UNESCAPED_UNICODE),
            'active'=>true,
            'created_at'=>now(),
            'updated_at'=>now(),
        ]);
    }

    private function priceFactorR91(string $category): float
    {
        return match($category){
            'table'=>5.25,
            'card_back'=>3.50,
            'emoji_pack'=>3.25,
            'effect'=>3.50,
            'profile_cover'=>3.10,
            'profile_frame'=>3.00,
            'badge'=>3.00,
            'name_color','text_color','name_frame'=>2.85,
            'xp_booster'=>2.25,
            'competition_ticket'=>1.10,
            default=>3.00,
        };
    }

    private function luxuryRoundR91(int $raised): int
    {
        if($raised<1000) return (int)(ceil($raised/50)*50);
        if($raised<10000) return (int)(ceil($raised/250)*250);
        return (int)(ceil($raised/500)*500);
    }

    /** R9.1: catch legacy active rows that are not part of the curated PHP catalog, exactly once. */
    private function normalizeAllActivePricesR91(): void
    {
        DB::table('store_items')->where('active',true)->where('category','!=','pasha')->orderBy('id')->chunkById(100,function($rows){
            foreach($rows as $row){
                $payload=json_decode((string)($row->payload ?? '{}'),true);
                if(!is_array($payload)) $payload=[];
                if(!empty($payload['r91_price_normalized'])) continue;
                $base=(int)($row->price ?? 0);
                $price=$base>0?$this->luxuryRoundR91((int)round($base*$this->priceFactorR91((string)$row->category))):0;
                $payload['r91_price_normalized']=true;
                $payload['r91_base_price']=$base;
                DB::table('store_items')->where('id',$row->id)->update(['price'=>$price,'payload'=>json_encode($payload,JSON_UNESCAPED_UNICODE),'updated_at'=>now()]);
            }
        });
    }

    private function v183Price(array $item): int
    {
        $price=(int)($item['price'] ?? 0);
        if($price<=0) return $price;
        if(!empty($item['payload']['b304'])) return $price; // B304 prices are authoritative and match Flutter exactly.
        $category=(string)($item['category'] ?? '');
        if($category==='pasha') return $price;
        // R9.1 luxury economy. Pasha remains unchanged; tables are the premium anchor.
        $raised=(int)round($price*$this->priceFactorR91($category));
        return $this->luxuryRoundR91($raised);
    }



